if($_SERVER['REQUEST_METHOD']==='POST'&&in_array((string)($_POST['action']??''),['availability_save','scope_blocks_save'],true)){
  $returnPanel=(string)($_POST['action']==='scope_blocks_save'?'schooldays':'availability');
  try{
    if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Phiên làm việc đã hết hạn. Hãy tải lại trang và lưu lại.');
    if($_POST['action']==='availability_save'){
      $saveType=in_array((string)($_POST['target_type']??''),['teacher','class'],true)?(string)$_POST['target_type']:'';
