      $field=$saveType==='teacher'?'blocked':'class_blocked';
      foreach((array)$data[$field]as$key=>$row)if((string)($row[$saveType]??'')===$saveTarget)unset($data[$field][$key]);
      foreach(array_values(array_unique(array_map('strval',(array)($_POST['busy_slots']??[]))))as$key){
        if(!preg_match('/^(2|3|4|5|6|7|8)\|(Sáng|Chiều)\|([1-8])$/u',$key,$m))continue;
        $row=['day'=>(int)$m[1],'session'=>$m[2],'period'=>(int)$m[3],'key'=>$key,$saveType=>$saveTarget];
        $data[$field][hash('sha256',$saveTarget.'|'.$key)]=$row;
      }
      if(!ttb_save($data))throw new RuntimeException('Không ghi được dữ liệu ràng buộc.');
      flash('Đã lưu bảng bận của '.$saveTarget.' trong phiên bản tuần hiện tại.','success');
