    }
    $saveScope=in_array((string)($_POST['scope']??''),['school','grade','class'],true)?(string)$_POST['scope']:'school';
    $saveValue=trim((string)($_POST['scope_value']??''));
    if($saveScope!=='school'&&$saveValue==='')throw new RuntimeException('Chưa chọn khối hoặc lớp cần lưu.');
    $data['scope_blocks']=array_values(array_filter((array)$data['scope_blocks'],fn($row)=>(string)($row['scope']??'')!==$saveScope||(string)($row['value']??'')!==$saveValue));
    foreach(array_values(array_unique(array_map('strval',(array)($_POST['locked_slots']??[]))))as$key){
      if(!preg_match('/^(2|3|4|5|6|7|8)\|(Sáng|Chiều)\|([1-8])$/u',$key,$m))continue;
      $data['scope_blocks'][]=['scope'=>$saveScope,'value'=>$saveValue,'day'=>(int)$m[1],'session'=>$m[2],'period'=>(int)$m[3],'key'=>$key];
