(function(){
 var settings=document.getElementById('rulesSettings'),week=document.querySelector('.week-settings');
 function showPanel(key){var returnPanel=document.getElementById('returnPanel');if(returnPanel)returnPanel.value=key;document.querySelectorAll('[data-panel]').forEach(function(x){x.classList.toggle('active',x.dataset.panel===key)});document.querySelectorAll('[data-content]').forEach(function(x){x.classList.toggle('active',x.dataset.content===key)});if(settings)settings.classList.toggle('d-none',key==='availability'||key==='schooldays');if(week)week.classList.toggle('d-none',key!=='teacher');var url=new URL(location.href);url.searchParams.set('panel',key);history.replaceState(null,'',url)}
 document.querySelectorAll('[data-panel]').forEach(function(b){b.addEventListener('click',function(){showPanel(b.dataset.panel)})});
 var type=document.getElementById('availabilityType'),target=document.getElementById('availabilityTarget'),form=document.getElementById('availabilityPicker');
 var options={teacher:<?=json_encode(array_values($teachers),JSON_UNESCAPED_UNICODE)?>,class:<?=json_encode(array_values($classes),JSON_UNESCAPED_UNICODE)?>};
 function fillTargets(keep){var list=options[type.value]||[],wanted=keep?target.dataset.current:'';target.innerHTML='';list.forEach(function(value){var option=document.createElement('option');option.value=value;option.textContent=value;if(value===wanted)option.selected=true;target.appendChild(option)});target.dataset.current=target.value||''}
 if(type&&target){fillTargets(true);type.addEventListener('change',function(){target.dataset.current='';fillTargets(false);form.submit()});target.addEventListener('change',function(){form.submit()})}
